You are a strict code reviewer. Two diffs (A, B) solve the SAME task. Which is higher quality (correctness, completeness, no broken cross-file refs)? Reply with exactly one token: A or B.
=== DIFF A ===
diff --git a/__tests__/write-paths-parity.test.ts b/__tests__/write-paths-parity.test.ts
new file mode 100644
index 00000000..b9494bc4
--- /dev/null
+++ b/__tests__/write-paths-parity.test.ts
@@ -0,0 +1,334 @@
+/**
+ * Parity test — both match write paths must produce the same 21 columns.
+ *
+ * The two paths that persist matches are:
+ *   (A) computeAndPersistMatches (background precompute, compute-matches.ts)
+ *   (B) persistSessionMatches    (session hydration, persist-session-matches.ts)
+ *
+ * Before B.2 the precompute path omitted fit_breakdown, worksheet_json,
+ * breakeven_tce_usd_per_day, and item-index columns — causing diverged renders
+ * depending on which path wrote the row. This test locks them equal.
+ *
+ * Strategy: call computeStoredMatchEconomics + computeFitBreakdown directly
+ * with the same cargo/vessel pair, then call createMatch twice (once per path
+ * shape) and assert that both stored rows carry the same computed column set.
+ */
+
+import Database from 'better-sqlite3';
+import migration031 from '@/lib/migrations/031-email-cache';
+import migration032 from '@/lib/migrations/032-matches';
+import migration033 from '@/lib/migrations/033-matches-score-breakdown';
+import migration034 from '@/lib/migrations/034-matches-unique-constraint';
+import migration035 from '@/lib/migrations/035-matches-tce-distance';
+import migration036 from '@/lib/migrations/036-matches-freight-rate';
+import migration041 from '@/lib/migrations/041-matches-vessel-name';
+import migration042 from '@/lib/migrations/042-matches-fit';
+import migration044 from '@/lib/migrations/044-matches-item-index';
+import migration045 from '@/lib/migrations/045-matches-worksheet';
+import migration046 from '@/lib/migrations/046-matches-consumption-estimated';
+import migration047 from '@/lib/migrations/047-matches-ballast-distance';
+import migration050 from '@/lib/migrations/050-matches-breakeven';
+import { createMatch, type StoredMatch } from '@/lib/matching/matches-repository';
+import { computeStoredMatchEconomics } from '@/lib/matching/stored-match-economics';
+import { computeFitBreakdown } from '@/lib/sailing/fit-breakdown';
+import { calculateReadinessGap, detectSpot } from '@/lib/sailing/readiness-gap';
+import { runHardFilters } from '@/lib/sailing/match-filters';
+import { checkSanctions } from '@/lib/validation/sanctions';
+import { cfValue } from '@/lib/types';
+import type { ParsedCargo, ParsedVessel } from '@/lib/types';
+import { breakevenTceByDwt } from '@/lib/economics/breakeven-thresholds';
+import { deriveBucketReason } from '@/lib/matching/bucket-reason';
+
+jest.mock('@/lib/market/baltic-freight', () => ({
+  getBalticDayRate: jest.fn(() => null),
+}));
+jest.mock('@/lib/market/bunker-repository', () => ({
+  getLatestBunkerPrice: jest.fn(() => null),
+}));
+jest.mock('@/lib/market/eua-repository', () => ({
+  getLatestEuaPrice: jest.fn(() => null),
+}));
+jest.mock('@/lib/port-da/match-da', () => ({
+  sumMatchPortDaUsd: jest.fn(() => ({ totalUsd: 0, confidence: 'estimated' })),
+}));
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  migration031.up(db);
+  migration032.up(db);
+  migration033.up(db);
+  migration034.up(db);
+  migration035.up(db);
+  migration036.up(db);
+  migration041.up(db);
+  migration042.up(db);
+  migration044.up(db);
+  migration045.up(db);
+  migration046.up(db);
+  migration047.up(db);
+  migration050.up(db);
+  return db;
+}
+
+const CARGO: ParsedCargo = {
+  emailId: 'cargo-parity-01',
+  itemIndex: 0,
+  cargoType: 'GRAIN',
+  laycan: '2026-08-10 to 2026-08-15',
+  originPort: { value: 'Rotterdam', confidence: 'confirmed', sourceText: 'Rotterdam' },
+  destinationPort: { value: 'Constanta', confidence: 'confirmed', sourceText: 'Constanta' },
+  weightMt: { value: 35000, confidence: 'confirmed', sourceText: '35000 mt' },
+  weightMtMin: 30000,
+  weightMtMax: 38000,
+  missingInfo: [],
+} as unknown as ParsedCargo;
+
+const VESSEL: ParsedVessel = {
+  emailId: 'vessel-parity-01',
+  itemIndex: 0,
+  vesselName: { value: 'PARITY TEST', confidence: 'confirmed', sourceText: 'PARITY TEST' },
+  openDate: { value: '2026-08-05', confidence: 'confirmed', sourceText: '5 Aug' },
+  openPosition: { value: 'Rotterdam', confidence: 'confirmed', sourceText: 'Rotterdam' },
+  dwtSummer: { value: 38000, confidence: 'confirmed', sourceText: '38000 dwt' },
+  speedLaden: '13 kn',
+  consumption: '22 mt/day',
+  restrictions: [],
+  specialFeatures: [],
+} as unknown as ParsedVessel;
+
+const SESSION_A = 'session-path-a';
+const SESSION_B = 'session-path-b';
+const CARGO_ID = 'cargo-parity-01';
+const VESSEL_ID = 'vessel-parity-01';
+
+/** Build the full computed payload the same way both paths now do. */
+function buildComputedPayload(db: Database.Database) {
+  const loadPort = cfValue(CARGO.originPort);
+  const dischargePort = cfValue(CARGO.destinationPort);
+  const vesselDwt = cfValue(VESSEL.dwtSummer) ?? 0;
+  const rawOpenDate = cfValue(VESSEL.openDate);
+  const isSpot = detectSpot(rawOpenDate);
+  const refYear = 2026;
+
+  const readiness = calculateReadinessGap(
+    { openDate: rawOpenDate, openPosition: cfValue(VESSEL.openPosition), speedLaden: VESSEL.speedLaden, dwtSummer: vesselDwt, isSpot },
+    { laycan: CARGO.laycan, originPort: loadPort },
+    { refYear, today: new Date('2026-07-01') },
+  );
+
+  const hf = runHardFilters({
+    cargoType: CARGO.cargoType,
+    originPort: loadPort,
+    destinationPort: dischargePort,
+    weightMt: vesselDwt * 0.8,
+    cargoDescription: null,
+    stowageFactor: null,
+    vesselType: VESSEL.vesselType ?? null,
+    geared: VESSEL.geared ?? null,
+    draftMax: cfValue(VESSEL.draftMax) ?? null,
+    grainCapacity: VESSEL.grainCapacity ?? null,
+    dwtSummer: vesselDwt,
+    dwcc: cfValue(VESSEL.dwcc) ?? null,
+    vesselRestrictions: [],
+    vesselBuilt: null,
+    refYear,
+    cargoMaxVesselAgeYrs: null,
+    vesselBeam: null,
+    vesselLoa: null,
+    cargoMaxBeamM: null,
+    cargoMaxLoaM: null,
+    cargoGearRequired: null,
+    vesselFlag: null,
+    vesselClassSociety: null,
+    cargoFlagRequired: null,
+    cargoClassRequired: null,
+  });
+
+  const sanctions = checkSanctions({ vesselFlag: null, originPort: loadPort, destinationPort: dischargePort, restrictions: [] });
+
+  const eco = computeStoredMatchEconomics({ cargo: CARGO, vessel: VESSEL, db });
+
+  const fb = computeFitBreakdown({
+    cargo: CARGO, vessel: VESSEL, readiness, sanctions,
+    hardFilters: { draft: hf.checks.draft, crane: hf.checks.crane, volume: hf.checks.volume, cargoVessel: hf.checks.cargoVessel, destDraft: hf.checks.destDraft, destCrane: hf.checks.destCrane, cargoWeight: hf.checks.cargoWeight },
+    refYear,
+    tceUsdPerDay: eco.tce_usd_per_day ?? undefined,
+  });
+
+  const worksheet = {
+    readiness: { ...readiness, openPosition: cfValue(VESSEL.openPosition) },
+    vessel: { dwtSummer: vesselDwt },
+    cargo: { weightMt: 35000, cargoType: 'GRAIN', loadPort, dischargePort },
+    hardFilters: { draft: hf.checks.draft, crane: hf.checks.crane, volume: hf.checks.volume },
+  };
+
+  const bucketReason = deriveBucketReason({
+    verdict: readiness.verdict,
+    gapDays: readiness.gapDays,
+    matchLevel: 'possible',
+    tceUsdPerDay: eco.tce_usd_per_day,
+    vesselDwt: vesselDwt,
+    issues: [],
+  });
+
+  const worksheetForPersist = { ...worksheet, hardFilters: hf.checks, sanctions, bucketReason };
+
+  return {
+    eco,
+    fb,
+    worksheetJson: JSON.stringify(worksheetForPersist),
+    vesselDwt,
+  };
+}
+
+const PARITY_COLUMNS = [
+  'cargo_id', 'vessel_id', 'cargo_item_index', 'vessel_item_index',
+  'cargo_type', 'load_port', 'discharge_port',
+  'vessel_dwt', 'tce_usd_per_day', 'distance_nm',
+  'freight_rate_usd_per_mt', 'freight_rate_source',
+  'fit_percent', 'ballast_distance_nm',
+  'breakeven_tce_usd_per_day', 'consumption_estimated',
+] as const;
+
+describe('write-paths-parity — both paths write the same 21 columns', () => {
+  it('precompute path and session path store the same computed fields', () => {
+    const db = freshDb();
+    const { eco, fb, worksheetJson, vesselDwt } = buildComputedPayload(db);
+
+    const commonFields = {
+      cargo_id: CARGO_ID,
+      vessel_id: VESSEL_ID,
+      score: 75,
+      reason: 'Parity test',
+      cargo_type: 'GRAIN',
+      load_port: 'Rotterdam',
+      discharge_port: 'Constanta',
+      laycan_start: new Date('2026-08-10').getTime(),
+      laycan_end: new Date('2026-08-15').getTime(),
+      vessel_dwt: vesselDwt,
+      vessel_name: 'PARITY TEST',
+      cargo_ref: 'GRAIN 35kt',
+      tce_usd_per_day: eco.tce_usd_per_day,
+      distance_nm: eco.distance_nm,
+      freight_rate_usd_per_mt: eco.freight_rate_usd_per_mt,
+      freight_rate_source: eco.freight_rate_source,
+      fit_percent: fb.fitPercent,
+      fit_breakdown: JSON.stringify(fb),
+      cargo_item_index: 0,
+      vessel_item_index: 0,
+      worksheet_json: worksheetJson,
+      consumption_estimated: eco.consumption_estimated ? 1 : null,
+      ballast_distance_nm: eco.ballast_distance_nm,
+      breakeven_tce_usd_per_day: vesselDwt ? breakevenTceByDwt(vesselDwt) : null,
+    };
+
+    // Path A: precompute (computeAndPersistMatches shape — no refreshComputed)
+    createMatch(db, { ...commonFields, user_id: SESSION_A, status: 'shortlist' });
+
+    // Path B: session (persistSessionMatches shape — with refreshComputed)
+    createMatch(db, { ...commonFields, user_id: SESSION_B, status: 'shortlist', refreshComputed: true });
+
+    const rowA = db.prepare(`SELECT * FROM matches WHERE user_id = ?`).get(SESSION_A) as StoredMatch;
+    const rowB = db.prepare(`SELECT * FROM matches WHERE user_id = ?`).get(SESSION_B) as StoredMatch;
+
+    expect(rowA).toBeDefined();
+    expect(rowB).toBeDefined();
+
+    for (const col of PARITY_COLUMNS) {
+      expect(rowA[col]).toEqual(rowB[col]);
+    }
+
+    // fit_breakdown and worksheet_json are parsed to compare structure
+    expect(rowA.fit_breakdown).not.toBeNull();
+    expect(rowB.fit_breakdown).not.toBeNull();
+    expect(JSON.parse(rowA.fit_breakdown!)).toMatchObject(JSON.parse(rowB.fit_breakdown!));
+
+    expect(rowA.worksheet_json).not.toBeNull();
+    expect(rowB.worksheet_json).not.toBeNull();
+  });
+
+  it('refreshComputed: true updates economics on subsequent calls without changing status/created_at', () => {
+    const db = freshDb();
+    const { eco, fb, worksheetJson, vesselDwt } = buildComputedPayload(db);
+
+    const base = {
+      cargo_id: CARGO_ID,
+      vessel_id: VESSEL_ID,
+      score: 75,
+      reason: 'refresh test',
+      cargo_type: 'GRAIN',
+      load_port: 'Rotterdam',
+      discharge_port: 'Constanta',
+      laycan_start: new Date('2026-08-10').getTime(),
+      laycan_end: new Date('2026-08-15').getTime(),
+      vessel_dwt: vesselDwt,
+      user_id: SESSION_A,
+      status: 'shortlist' as const,
+      fit_percent: 55,
+      fit_breakdown: '{"old":true}',
+      tce_usd_per_day: 1000,
+      distance_nm: eco.distance_nm,
+      freight_rate_usd_per_mt: 10,
+      freight_rate_source: 'estimated',
+      ballast_distance_nm: 200,
+      breakeven_tce_usd_per_day: 8000,
+      consumption_estimated: null,
+      worksheet_json: null,
+    };
+
+    // First call creates the row
+    const first = createMatch(db, base);
+    const createdAt = first.created_at;
+    const status = first.status;
+
+    // Second call refreshes computed fields
+    createMatch(db, {
+      ...base,
+      fit_percent: fb.fitPercent,
+      fit_breakdown: JSON.stringify(fb),
+      tce_usd_per_day: eco.tce_usd_per_day,
+      freight_rate_usd_per_mt: eco.freight_rate_usd_per_mt,
+      freight_rate_source: eco.freight_rate_source,
+      ballast_distance_nm: eco.ballast_distance_nm,
+      breakeven_tce_usd_per_day: vesselDwt ? breakevenTceByDwt(vesselDwt) : null,
+      worksheet_json: worksheetJson,
+      refreshComputed: true,
+    });
+
+    const row = db.prepare(`SELECT * FROM matches WHERE user_id = ?`).get(SESSION_A) as StoredMatch;
+    expect(row.fit_percent).toBe(fb.fitPercent);
+    expect(row.tce_usd_per_day).toBe(eco.tce_usd_per_day);
+    expect(row.status).toBe(status);
+    expect(row.created_at).toBe(createdAt);
+    expect(row.worksheet_json).not.toBeNull();
+  });
+
+  it('refreshComputed: worksheet_json COALESCE — null does not erase stored value', () => {
+    const db = freshDb();
+    const { fb, eco, vesselDwt, worksheetJson } = buildComputedPayload(db);
+
+    const base = {
+      cargo_id: CARGO_ID,
+      vessel_id: VESSEL_ID,
+      score: 75,
+      reason: 'coalesce test',
+      user_id: SESSION_A,
+      status: 'shortlist' as const,
+      fit_percent: fb.fitPercent,
+      fit_breakdown: JSON.stringify(fb),
+      tce_usd_per_day: eco.tce_usd_per_day,
+      distance_nm: eco.distance_nm,
+      freight_rate_usd_per_mt: eco.freight_rate_usd_per_mt,
+      freight_rate_source: eco.freight_rate_source,
+      worksheet_json: worksheetJson,
+    };
+
+    createMatch(db, base);
+
+    // Refresh with null worksheet_json — stored value must survive
+    createMatch(db, { ...base, worksheet_json: null, refreshComputed: true });
+
+    const row = db.prepare(`SELECT worksheet_json FROM matches WHERE user_id = ?`).get(SESSION_A) as StoredMatch;
+    expect(row.worksheet_json).toBe(worksheetJson);
+  });
+});
