 /**
  * Compute matches for a session and persist them to the DB.
@@ -99,6 +103,56 @@ export async function computeAndPersistMatches(
     const freight_rate_source = eco.freight_rate_source;
     const consumption_estimated = eco.consumption_estimated ? 1 : null;

+    // Patch economics component with the stored TCE so fit_breakdown is consistent
+    // with the tce_usd_per_day column (mirrors persist-session-matches.ts).
+    const liveFitBreakdown = m.fitBreakdown && tce_usd_per_day != null
+      ? patchEconomicsComponent(m.fitBreakdown, tce_usd_per_day, vesselDwt)
+      : m.fitBreakdown;
