+    // writes a non-null worksheet_json (parity with persist-session-matches).
+    const bucketReason = m.readiness
+      ? deriveBucketReason({
+          verdict: m.readiness.verdict,
+          gapDays: m.readiness.gapDays,
+          matchLevel: m.matchLevel,
+          tceUsdPerDay: tce_usd_per_day,
+          vesselDwt: vesselDwt || null,
+          issues: m.issues ?? [],
+        })
+      : undefined;
+    const worksheetJson = m.readiness && cargo && vessel
+      ? JSON.stringify({
+          readiness: { ...m.readiness, openPosition: cfValue(vessel.openPosition) },
+          vessel: {
+            draftMax: cfValue(vessel.draftMax) ?? null,
+            grainCapacity: vessel.grainCapacity ?? null,
+            grainCapacityUnit: vessel.grainCapacityUnit ?? null,
+            geared: vessel.geared ?? null,
+            vesselType: vessel.vesselType ?? null,
+            flag: vessel.flag ?? null,
+            built: vessel.built ?? null,
+            pandi: vessel.pandi ?? null,
+            classSociety: vessel.classSociety ?? null,
+            lastCargoes: vessel.lastCargoes ?? null,
+            dwtSummer: cfValue(vessel.dwtSummer) ?? null,
+            dwcc: cfValue(vessel.dwcc) ?? null,
+          },
+          cargo: {
+            weightMt: cfValue(cargo.weightMt) ?? null,
+            weightMtEffective: resolveCargoWeight(cargo) ?? null,
+            cargoType,
+            loadPort,
+            dischargePort,
+          },
+          hardFilters: m.hardFilters ?? { draft: { pass: true }, crane: { pass: true }, volume: { pass: true } },
+          sanctions: m.sanctions,
+          bucketReason,
+        })
+      : null;
+
     createMatch(db, {
       cargo_id: m.cargoEmailId,
       vessel_id: m.vesselEmailId,
@@ -119,8 +173,14 @@ export async function computeAndPersistMatches(
       freight_rate_source,
       vessel_name: vessel ? (cfValue(vessel.vesselName) || null) : null,
       cargo_ref: cargo ? (cfValue(cargo.cargoDescription) || null) : null,
+      fit_percent: liveFitPercent ?? null,
+      fit_breakdown: liveFitBreakdown ? JSON.stringify(liveFitBreakdown) : null,
+      cargo_item_index: m.cargoItemIndex,
+      vessel_item_index: m.vesselItemIndex,
+      worksheet_json: worksheetJson,
       consumption_estimated,
       ballast_distance_nm: eco.ballast_distance_nm ?? null,
+      breakeven_tce_usd_per_day: vesselDwt ? breakevenTceByDwt(vesselDwt) : null,
     });
   }

