 }

 export interface ListMatchesOptions {
@@ -390,6 +398,52 @@ export function createMatch(db: Database.Database, input: CreateMatchInput): Sto
     result = stmt.run(input.cargo_id, input.vessel_id, input.score, input.reason, status, user_id, now, now);
   }

+  // refreshComputed: update live economics + fit on the existing row after
+  // INSERT OR IGNORE (first-call creates the row; subsequent calls refresh it).
+  // worksheet_json uses COALESCE so a null input never erases a stored value.
+  // status and created_at are never touched — only the computed columns change.
+  if (input.refreshComputed && hasFitColumns(db)) {
+    const withWorksheet = hasWorksheetColumn(db);
+    const withBallast = hasBallastDistanceColumn(db);
+    const withBreakeven = hasBreakevenColumn(db);
+    const withConsEst = hasConsumptionEstimatedColumn(db);
+    let refreshSql = `UPDATE matches SET
+      tce_usd_per_day = ?,
+      freight_rate_usd_per_mt = ?,
+      freight_rate_source = ?,
+      fit_percent = ?,
+      fit_breakdown = ?,
+      updated_at = ?`;
+    const refreshArgs: Array<string | number | null> = [
+      input.tce_usd_per_day ?? null,
+      input.freight_rate_usd_per_mt ?? null,
+      input.freight_rate_source ?? null,
+      input.fit_percent ?? null,
+      input.fit_breakdown ?? null,
+      Date.now(),
+    ];
+    if (withWorksheet) {
+      refreshSql += `, worksheet_json = COALESCE(?, worksheet_json)`;
+      refreshArgs.push(input.worksheet_json ?? null);
+    }
+    if (withBallast) {
+      refreshSql += `, ballast_distance_nm = ?`;
+      refreshArgs.push(input.ballast_distance_nm ?? null);
+    }
+    if (withBreakeven) {
+      refreshSql += `, breakeven_tce_usd_per_day = ?`;
+      refreshArgs.push(input.breakeven_tce_usd_per_day ?? null);
+    }
+    if (withConsEst) {
+      refreshSql += `, consumption_estimated = ?`;
+      refreshArgs.push(input.consumption_estimated ?? null);
+    }
+    refreshSql += ` WHERE cargo_id = ? AND vessel_id = ?
+      AND (user_id = ? OR (user_id IS NULL AND ? IS NULL))`;
+    refreshArgs.push(input.cargo_id, input.vessel_id, user_id, user_id);
+    db.prepare(refreshSql).run(...refreshArgs);
+  }
+
   if (result.changes === 0) {
